{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We included children (defined as ≤18 years old) who were attending school, and their close contacts (family and household members, teachers, school support staff). We excluded home-schooled children and their close contacts, and schools with student numbers below 20. For study outcomes, we included infections traced to a school index case with a COVID-19 positive test. We updated inclusion criteria of study types to include: 1) Cohort studies... 2) Cross-sectional studies... 3) Pre-post studies... We excluded household studies unless specifically linked to school outbreaks; and studies where rates are measured in schools and without comparison of community rates.",
      "reason": "The manuscript explicitly defines the population (children ≤18, contacts), settings (schools), and study designs (cohort, cross-sectional, pre-post) used for eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We included articles in peer-reviewed journals and pre-prints, and excluded comments, conference abstracts and interviews.",
      "reason": "The manuscript specifies the publication status (peer-reviewed journals and pre-prints) and report types (excluding comments, conference abstracts, and interviews) for eligibility."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not report excluding studies specifically because outcomes were not measured versus not reported; this is not a relevant distinction for the eligibility criteria described."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "We found 11 cohort studies [13-17,24-29] that investigated secondary infection attack ( Table 1 and Table 2 ) and one cross-sectional studies [18] that investigated SARS-CoV-2 positivity compared to community rates ( Table 3 and Table 4 ).",
      "reason": "The manuscript specifies how studies were grouped for synthesis (cohort studies investigating secondary infection attack rates and cross-sectional studies investigating positivity rates compared to community rates)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "We excluded household studies unless specifically linked to school outbreaks; and studies where rates are measured in schools and without comparison of community rates.",
      "reason": "The manuscript provides a rationale for excluding studies that do not meet the specific comparative criteria (e.g., excluding studies without comparison of community rates)."
    }
  ],
  "confidence": 100
}

